package com.processVisualisation.virtualKitchen.ai.provider.config;

import org.springframework.boot.context.properties.ConfigurationProperties;
import org.springframework.stereotype.Component;

import lombok.Data;

/**
 * Binds configuration properties under the {@code ai.deepinfra} prefix,
 * including the API key, base URL, chat endpoint, default model and request
 * timeout used to call DeepInfra's OpenAI-compatible chat completions API.
 * Getters and setters are generated by Lombok's {@link Data} annotation.
 */
@Data
@Component
@ConfigurationProperties(prefix = "ai.deepinfra")
public class DeepInfraProperties {

    private String apiKey;
    private String baseUrl;
    private String chatEndpoint;
    private String defaultModel;
    private Long timeoutMs;

    /**
     * Sent as {@code reasoning_effort} when set (e.g. {@code none} to switch thinking off on reasoning models);
     * blank leaves the parameter out and the model's own default applies.
     */
    private String reasoningEffort;

    /**
     * When true, a request carrying a JSON Schema is sent as {@code response_format: json_schema}; when false it
     * degrades to plain JSON mode ({@code json_object}) and the backend's own validation enforces the shape.
     */
    private boolean jsonSchemaEnabled = true;

    /** Image generation ({@code ai.deepinfra.image.*}); shares the API key, base URL and REST client above. */
    private Image image = new Image();

    /** Text-to-speech ({@code ai.deepinfra.tts.*}); shares the API key, base URL and REST client above. */
    private Tts tts = new Tts();

    @Data
    public static class Tts {

        /** DeepInfra's OpenAI-style speech endpoint; the native {@code /v1/inference/<model>} route also answers here. */
        private volatile String endpoint = "/v1/audio/speech";
        /** Used when the registry model names none. */
        private volatile String model = "XiaomiMiMo/MiMo-V2.5-tts";
        /** Built-in voice (MiMo: Mia, Chloe, Milo, Dean, mimo_default, …) or a custom voice id. */
        private volatile String voice = "Mia";
        /** wav, mp3 or opus: the formats narration can store and play. */
        private volatile String responseFormat = "wav";
        /** Only used if the provider answers with raw PCM, which is then wrapped as WAV. */
        private volatile int pcmSampleRateHz = 24000;
        /** Optional speaking-style instruction, sent as {@code extra_body.instructions} only when set. */
        private volatile String stylePrompt;
    }

    @Data
    public static class Image {

        private String endpoint = "/v1/openai/images/generations";
        private String model;
        private Integer width = 1024;
        private Integer height = 1024;
        /** Sent as {@code n}. Only the first image is used, so anything above 1 is paid for and discarded. */
        private Integer count = 1;
    }
}
